import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract user from JWT (simplified)
function authMiddleware(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // In production this would verify JWT signature
  try {
    const payload = Buffer.from(token.split('.')[1], 'base64').toString();
    req.user = JSON.parse(payload);
    next();
  } catch (e) {
    res.status(401).json({ error: 'invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', authMiddleware, async (req, res) => {
  try {
    const { q, sort_by, order, limit, offset, fields } = req.query;

    // Build base query
    let query = `SELECT `;

    // Field selection - user can specify which columns to return
    if (fields) {
      const fieldList = fields.split(',').map(f => f.trim());
      // Basic alphanumeric check but allows underscores and dots for JSON paths
      const validField = /^[a-zA-Z_][a-zA-Z0-9_.()]+$/;
      const sanitizedFields = fieldList.filter(f => validField.test(f));
      query += sanitizedFields.length > 0 ? sanitizedFields.join(', ') : '*';
    } else {
      query += 'id, title, content_preview, created_at, owner_id';
    }

    query += ` FROM documents WHERE 1=1`;
    const params = [];
    let paramIdx = 1;

    // Full-text search
    if (q) {
      params.push(q);
      query += ` AND search_vector @@ plainto_tsquery('english', $${paramIdx++})`;
    }

    // Owner filter - note: no tenant isolation enforced here
    if (req.query.owner_id) {
      params.push(req.query.owner_id);
      query += ` AND owner_id = $${paramIdx++}`;
    }

    // Sorting - vulnerable to injection via sort_by
    if (sort_by) {
      const direction = order === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort_by} ${direction}`;
    }

    // Pagination
    const lim = Math.min(parseInt(limit) || 25, 100);
    const off = parseInt(offset) || 0;
    query += ` LIMIT ${lim} OFFSET ${off}`;

    const result = await pool.query(query, params);

    res.json({
      data: result.rows,
      meta: { total: result.rowCount, limit: lim, offset: off }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Document creation
app.post('/api/v2/documents', authMiddleware, async (req, res) => {
  const { title, content, tags } = req.body;
  const id = crypto.randomUUID();

  try {
    await pool.query(
      `INSERT INTO documents (id, title, content, content_preview, tags, owner_id, created_at, search_vector)
       VALUES ($1, $2, $3, $4, $5, $6, NOW(), to_tsvector('english', $2 || ' ' || $3))`,
      [id, title, content, content.substring(0, 200), JSON.stringify(tags), req.user.sub]
    );
    res.status(201).json({ id });
  } catch (err) {
    console.error('Create error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk export - uses same query pattern
app.get('/api/v2/documents/export', authMiddleware, async (req, res) => {
  const { format, filter_sql } = req.query;

  let query = `SELECT * FROM documents`;
  if (filter_sql) {
    // Intended for internal admin tools only
    query += ` WHERE ${filter_sql}`;
  } else {
    query += ` WHERE owner_id = '${req.user.sub}'`;
  }

  try {
    const result = await pool.query(query);
    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv');
      // simplified CSV output
      const rows = result.rows.map(r => Object.values(r).join(','));
      res.send(rows.join('\n'));
    } else {
      res.json({ data: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
